.then(sismos => {
    window.currentSismosMarkers = [];

    const now = Date.now();
    const recentSismos = sismos.filter(sismo => (now - sismo.timestamp) <= 24 * 60 * 60 * 1000);

    if (recentSismos.length === 0) {
        const chatOutput = document.getElementById('chat-output');
        if (chatOutput) {
            chatOutput.insertAdjacentHTML('beforeend', '<div class="message bot"><div class="message-content"><span class="bubble" style="background:#f0fdf4; color:#166534; border:1px solid #bbf7d0;">Todo tranquilo. No se han registrado seísmos en España en las últimas 24 horas 😌</span></div></div>');
            chatOutput.scrollTop = chatOutput.scrollHeight;
        }
        return;
    }

    recentSismos.forEach(sismo => {
        let radius = 4;
        let color = '#9ca3af'; // gris por defecto

        // Escala Richter extendida (para prepararnos ante terremotos fuertes)
        if (sismo.mag < 2.0) {
            radius = 4; color = '#9ca3af'; // Micro
        } else if (sismo.mag < 3.0) {
            radius = 6; color = '#fbbf24'; // Menor
        } else if (sismo.mag < 4.0) {
            radius = 8; color = '#f97316'; // Ligero
        } else if (sismo.mag < 5.0) {
            radius = 12; color = '#ef4444'; // Moderado
        } else if (sismo.mag < 6.0) {
            radius = 18; color = '#dc2626'; // Fuerte
        } else if (sismo.mag < 7.0) {
