// Map logic
const map = window.currentMap;
const L = window.L;
if (!map || !L) { console.error('Mapa no inicializado'); return; }

// Handle Basemap Layers (Radio behavior)
if (layerId === 'popular' || layerId === 'red') {
    document.querySelectorAll('.filter-pill').forEach(btn => {
        if (btn.innerText.includes('Popular') || btn.innerText.includes('Red')) {
            btn.classList.remove('active');
        }
    });
    if (target) target.classList.add('active');
    return;
}

// Toggle Behavior for Data Layers
const isCurrentlyActive = target && target.classList.contains('active');

if (isCurrentlyActive) {
    // TOGGLE OFF
    target.classList.remove('active');
    target.style.background = 'transparent';

    if (layerId === 'incendios') {
        target.style.color = '#ef4444';
        if (window.effisLayers) { window.effisLayers.forEach(l => map.removeLayer(l)); window.effisLayers = []; }
        if (window.currentFireMarkers) { window.currentFireMarkers.forEach(l => map.removeLayer(l)); window.currentFireMarkers = []; }
    } else if (layerId === 'embalses') {
        target.style.color = '#3b82f6';
        if (window.waterLayers) { window.waterLayers.forEach(l => map.removeLayer(l)); window.waterLayers = []; }
    } else if (layerId === 'sismos') {
        target.style.color = '#f97316';
        if (window.currentSismosMarkers) { window.currentSismosMarkers.forEach(l => map.removeLayer(l)); window.currentSismosMarkers = []; }
    } else if (layerId === 'aire') {
        target.style.color = '#10b981';
        if (window.airLayers) { window.airLayers.forEach(l => map.removeLayer(l)); window.airLayers = []; }
    }
    return; // Stop here, we just toggled it off.
} else {
    // TOGGLE ON
    if (target) {
        target.classList.add('active');
        target.style.color = 'white';
        if (layerId === 'incendios') target.style.background = '#ef4444';
        if (layerId === 'embalses') target.style.background = '#3b82f6';
        if (layerId === 'sismos') target.style.background = '#f97316';
        if (layerId === 'aire') target.style.background = '#10b981';
    }
}

