const renderWidget = (name, symbol, val, limit) => {
    const hasData = val !== null && val !== undefined;
    const displayVal = hasData ? val : 'N/D';

    let viz = '';
    if (hasData) {
        const maxVisual = limit / 0.6;
        const pct = Math.min((val / maxVisual) * 100, 100);
        const color = val > limit ? '#ef4444' : (val > limit * 0.75 ? '#eab308' : '#10b981');

