        const maxVisual = limit / 0.6;
        const pct = Math.min((val / maxVisual) * 100, 100);
        const color = val > limit ? '#ef4444' : (val > limit * 0.75 ? '#eab308' : '#10b981');
        const valLength = (pct / 100) * gaugeLength;

        viz = `<div style="position:relative; width:80px; height:80px; display:flex; align-items:center; justify-content:center; margin: 4px auto 0;">
            <svg width="80" height="80" viewBox="0 0 80 80" style="transform: rotate(135deg);">
                <!-- Background track -->
                <circle cx="40" cy="40" r="28" fill="none" stroke="var(--header-border)" stroke-width="6" stroke-dasharray="${gaugeLength} ${gapLength}" stroke-linecap="round"></circle>
                <!-- Limit tick -->
                <circle cx="40" cy="40" r="28" fill="none" stroke="var(--text-secondary)" stroke-width="12" stroke-dasharray="1 ${C}" stroke-dashoffset="-${limitLength}" opacity="0.3"></circle>
                <!-- Value track -->
                <circle cx="40" cy="40" r="28" fill="none" stroke="${color}" stroke-width="6" stroke-dasharray="${valLength} ${C}" stroke-linecap="round"></circle>
