'dust_forecast': {
    type: 'wms',
    color: '#f59e0b',
    _isActive: false,
    _wmsLayer: null,
    fetchWmsLayer: async (map) => {
        // Llama al backend para obtener la URL del modelo de hoy (ej. AEMET o CAMS)
        try {
            const res = await fetch('/api/dust-forecast');
            const data = await res.json();
            if (data.url && data.layers) {
                const layer = window.L.tileLayer.wms(data.url, {
                    layers: data.layers,
                    format: 'image/png',
                    transparent: true,
                    opacity: 0.55,
                    zIndex: 400,
                    styles: data.styles || ''
                });
                layer.addTo(map);
                return layer;
            }
        } catch (e) {
            console.error('Error fetching dust forecast WMS:', e);
            // Fallback opcional a un WMS estático
        }
        return null;
    }
},

