        // --- GPS y Ahorro Gasolineras ---
        function getDistance(lat1, lon1, lat2, lon2) {
            const R = 6371; // km
            const dLat = (lat2 - lat1) * Math.PI / 180;
            const dLon = (lon2 - lon1) * Math.PI / 180;
            const a = Math.sin(dLat/2) * Math.sin(dLat/2) +
                      Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
                      Math.sin(dLon/2) * Math.sin(dLon/2);
            const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1-a));
            return R * c;
        }

        window.simulatedGPS = null;
        window.simulatedMarker = null;

        window.toggleGpsSimulator = function() {
            if (!window.currentMap || !window.L) return;
            const map = window.currentMap;

            const btn = document.getElementById('btn-simulate-gps');

            if (window.simulatedGPS) {
                window.simulatedGPS = null;
                if (window.simulatedMarker) {
                    map.removeLayer(window.simulatedMarker);
                    window.simulatedMarker = null;
                }
                if (btn) {
                    btn.style.background = 'var(--chat-bg)';
                    btn.style.color = 'var(--text-secondary)';
                }
                return;
            }

            // Activar en el centro de Jerez por defecto
            window.simulatedGPS = { lat: 36.685, lng: -6.126 };
            if (btn) {
                btn.style.background = 'var(--primary-color)';
                btn.style.color = 'white';
            }

            window.simulatedMarker = window.L.marker([window.simulatedGPS.lat, window.simulatedGPS.lng], {
                draggable: true,
                icon: window.L.divIcon({
                    html: '<div style="background:#3b82f6;width:16px;height:16px;border-radius:50%;border:3px solid white;box-shadow:0 2px 5px rgba(0,0,0,0.3);"></div>',
                    className: '',
                    iconSize: [22, 22],
                    iconAnchor: [11, 11]
                })
            }).addTo(map);

            window.simulatedMarker.bindTooltip("Mueve este punto para simular tu GPS", {permanent: true, direction: "top", offset: [0, -10]}).openTooltip();

            window.simulatedMarker.on('dragend', function(e) {
                const pos = e.target.getLatLng();
                window.simulatedGPS = { lat: pos.lat, lng: pos.lng };
                if (window.lastGasFilter) {
                    window.filterGasolineras(window.lastGasFilter);
                }
            });

            map.setView([window.simulatedGPS.lat, window.simulatedGPS.lng], 12);

            if (window.lastGasFilter) {
                window.filterGasolineras(window.lastGasFilter);
            }
        };

        window.lastGasFilter = null;

        window.filterGasolineras = function(mode) {
            window.lastGasFilter = mode;
            const filterObj = mapConfig.layers['gasolineras'];
            if (!filterObj || !filterObj._allData || !window.currentMap || !window.L) return;

            const map = window.currentMap;

            const executeFilter = (lat, lng) => {
                let filtered = [...filterObj._allData];

                filtered.forEach(s => {
                    s.distKm = getDistance(lat, lng, parseFloat(s.Latitud.replace(',','.')), parseFloat(s.Longitud.replace(',','.')));
                });

                if (mode === 'cercanas') {
                    filtered = filtered.sort((a, b) => a.distKm - b.distKm).slice(0, 3);
                } else if (mode === 'baratas_cercanas') {
                    filtered = filtered.filter(s => s.priceLevel === 1 && s.distKm <= 5);
                    filtered = filtered.sort((a, b) => a.distKm - b.distKm);
                }

                // Limpiar marcadores actuales
                if (filterObj._clusterGroup) {
                    filterObj._clusterGroup.clearLayers();
                } else {
                    filterObj._markers.forEach(m => {
                        if (map.hasLayer(m)) map.removeLayer(m);
                    });
                }
                filterObj._markers = [];

                if (filtered.length === 0) {
                    alert("No se encontraron gasolineras que cumplan este criterio en esta zona.");
                    return;
                }

                const boundsArr = [];

                filtered.forEach(item => {
                    const marker = filterObj.renderMarker(item, map);

                    marker.on('click', () => {
                        const popupData = filterObj.onMarkerClick(item);
                        const container = document.getElementById('map-ui-container');
                        if (!container) return;
                        document.getElementById('map-info-label').innerText = popupData.label;
                        document.getElementById('map-info-label').style.color = popupData.labelColor || filterObj.color;
                        document.getElementById('map-info-title').innerText = popupData.title;
                        document.getElementById('map-info-desc').innerHTML = popupData.desc;
                        const actionsDiv = document.getElementById('map-pill-actions');
                        if (actionsDiv) actionsDiv.style.display = popupData.showActions !== false ? 'flex' : 'none';
                        if (popupData.recenter) map.setView(popupData.recenter, 14);
                        container.style.opacity = '1';
                        container.style.pointerEvents = 'auto';
                        container.style.transform = 'translate(-50%, 0)';
                    });

                    filterObj._markers.push(marker);

                    if (filterObj._clusterGroup) {
                        filterObj._clusterGroup.addLayer(marker);
                    } else {
                        marker.addTo(map);
                    }

                    const latNum = parseFloat(item.Latitud.replace(',','.'));
                    const lngNum = parseFloat(item.Longitud.replace(',','.'));
                    boundsArr.push([latNum, lngNum]);
                });

                if (boundsArr.length > 0) {
                    map.fitBounds(boundsArr, { padding: [50, 50], maxZoom: 14 });
                }
            };

            if (window.simulatedGPS) {
                executeFilter(window.simulatedGPS.lat, window.simulatedGPS.lng);
            } else {
                if (navigator.geolocation) {
                    // Feedback visual mientras busca GPS
                    const oldText = document.getElementById('map-info-label').innerText;
                    document.getElementById('map-info-label').innerText = "Buscando GPS...";

                    navigator.geolocation.getCurrentPosition(
                        (pos) => {
                            document.getElementById('map-info-label').innerText = oldText;
                            executeFilter(pos.coords.latitude, pos.coords.longitude);
                        },
                        (err) => {
                            document.getElementById('map-info-label').innerText = oldText;
                            alert("No se pudo obtener la ubicación GPS o denegaste el permiso.");
                        }
                    );
                } else {
                    alert("Tu navegador no soporta Geolocalización.");
                }
            }
        };

