            }

            const chip = document.getElementById('chip-aviones-comerciales');
            if (chip) {
                chip.className = window.lastAvionesFilter === 'no_comerciales' ? 'map-chip active' : 'map-chip';
            }

            let displayData = filterObj._allData;
            if (filterObj.applyLocalFilter) {
                displayData = filterObj.applyLocalFilter(displayData);
            }

            if (filterObj._clusterGroup) {
                map.removeLayer(filterObj._clusterGroup);
                filterObj._clusterGroup.clearLayers();
                filterObj._clusterGroup = null;
            }
            if (filterObj._markers && filterObj._markers.length > 0) {
                filterObj._markers.forEach(m => map.removeLayer(m));
                filterObj._markers = [];
            }

            if (filterObj.useClustering) {
                filterObj._clusterGroup = window.L.markerClusterGroup({
                    maxClusterRadius: 40,
                    spiderfyOnMaxZoom: true,
                    showCoverageOnHover: false,
